@dataclass(frozen=True)
class Breakdown:
    total: Decimal
    tariff: Rule
    minutes: int

def breakdown(entry: datetime, exit: datetime, *, lost_ticket: bool = False, validated: bool = False) -> Breakdown:
    if entry.tzinfo is None and exit.tzinfo is not None:
        entry = entry.replace(tzinfo=exit.tzinfo)
    elif exit.tzinfo is None and entry.tzinfo is not None:
        exit = exit.replace(tzinfo=entry.tzinfo)
    if exit < entry:
        raise ValueError(f"exit {exit.isoformat()} is earlier than entry {entry.isoformat()}")
    duration = exit - entry
    if lost_ticket:
        rule, amount = Rule.LOST_TICKET, LOST_TICKET_FEE
    elif duration <= GRACE_PERIOD:
        rule, amount = Rule.GRACE, FREE
    elif _validated_free(duration, validated):
        rule, amount = Rule.VALIDATED, FREE
    elif duration > DAY:
        rule, amount = Rule.LONG_STAY, _long_stay_charge(entry, exit)
    elif duration > NIGHT_MINIMUM_STAY and _in_night_window(entry, exit):
        rule, amount = Rule.NIGHT, NIGHT_FLAT_RATE
    else:
        rule, amount = Rule.HOURLY, min(_hourly_charge(entry, exit), DAILY_CAP)
    return Breakdown(total=amount.normalize(), tariff=rule, minutes=round(duration / timedelta(minutes=1)))

def format_receipt(amount: Decimal) -> str:
    if amount == FREE:
        return FREE_RECEIPT
    return CURRENCY + format(amount, " .2f")
